import{_ as e,c as i,o as r,b0 as l}from"./chunks/framework.Dmsv_Tiv.js";const t="/media-docs/assets/640-202407050729.CEnEe1m2.webp",s="/media-docs/assets/20-50-55-510_512.D_jilu7T.gif",o="/media-docs/assets/tiger-jpg.DyOWKsYd.webp",n="/media-docs/assets/webp-support-1024x663-1.Crn-FD5y.jpg",h="data:image/webp;base64,",p="/media-docs/assets/bmp-vs-gif.D7Fw_Zpc.webp",d="/media-docs/assets/jpeg-vs-heif-1024x307.DKaNQQvz.webp",b="/media-docs/assets/1200px-SVG_logo.svg_.CaJCcwm8.webp",c="/media-docs/assets/pasted-image-0-3.BVaRh5bR.webp",q=JSON.parse('{"title":"LV010-常见文件格式","description":null,"frontmatter":{"title":"LV010-常见文件格式","date":"2025-09-19T16:13:52.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/image/img-file-format/126b08d7ce083aeabcd2d638","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-09-19T16:13:52.942Z","fulluuid":"abcd2d6386f34e148749aee24dd37821","useduuid":"abcd2d638"}},"headers":[],"relativePath":"sdoc/image/img-file-format/126b08d7ce083aeabcd2d638.md","filePath":"sdoc/01-图像/30-图像文件格式/LV010-常见文件格式.md","lastUpdated":1767537778000}'),u={name:"sdoc/image/img-file-format/126b08d7ce083aeabcd2d638.md"};function g(k,a,E,f,P,m){return r(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="lv010-常见文件格式" tabindex="-1">LV010-常见文件格式 <a class="header-anchor" href="#lv010-常见文件格式" aria-label="Permalink to &quot;LV010-常见文件格式&quot;">​</a></h1><h2 id="一、有哪些常见图片格式" tabindex="-1">一、有哪些常见图片格式 <a class="header-anchor" href="#一、有哪些常见图片格式" aria-label="Permalink to &quot;一、有哪些常见图片格式&quot;">​</a></h2><p>先来看一张从网上找的图：</p><img src="'+t+'" alt="图片"><p>这里其实也就是我们常见的一些图片格式，像png，jpeg，gif，bmp等等。但是这张图其实并不全，还有很多其他格式的图片：</p><blockquote><p>JPEG（或JPG） – 最为常见的图像格式 PNG – Web广泛使用的图像格式 GIF – 动画图像格式 WebP – JPEG&amp;PNG最佳替代图像格式 TIFF – 扫描仪最佳拍档图像格式 BMP – 过气的图像格式 HEIF – 手机照片常见图像格式 SVG – 可缩放矢量图形格式 EPS – 插画/排版设计矢量图像格式 PDF – 电子书常用文档格式 PSD – Photoshop文档格式 AI – Adobe Illustrator文档格式 XCF – GIMP图像编辑工具专属格式 INDD – Adobe InDesign文档格式 Raw – 数码相机图像存储文件格式</p></blockquote><h2 id="二、图片格式简介" tabindex="-1">二、图片格式简介 <a class="header-anchor" href="#二、图片格式简介" aria-label="Permalink to &quot;二、图片格式简介&quot;">​</a></h2><h3 id="_1-jpeg-或jpg-最为常见的图像格式" tabindex="-1">1. JPEG（或JPG）- 最为常见的图像格式 <a class="header-anchor" href="#_1-jpeg-或jpg-最为常见的图像格式" aria-label="Permalink to &quot;1. JPEG（或JPG）- 最为常见的图像格式&quot;">​</a></h3><h4 id="_1-1-简介" tabindex="-1">1.1 简介 <a class="header-anchor" href="#_1-1-简介" aria-label="Permalink to &quot;1.1 简介&quot;">​</a></h4><p>JPEG（或JPG），其全称为Joint Photographic Experts Group（联合图像专家组），是一种有损压缩、不带透明通道的0-10级压缩（11级压缩）光栅图像（位图）文件格式，适合作为共享图像。既然JPEG是“有损的”图像，也就是说使用此格式时，若减小文件大小，在一定程度上也会降低图像质量。JPEG是目前互联网上最常用的图像文件类型之一，因为它的可压缩性及浏览器/操作系统广泛支持。</p><p>大多数社交媒体平台（例如Facebook和Instagram）会自动将上传的图像文件转换为JPEG，且会根据不同场景使用固定的尺寸大小来控制图片的分辨率。</p><h4 id="_1-2-优缺点" tabindex="-1">1.2 优缺点 <a class="header-anchor" href="#_1-2-优缺点" aria-label="Permalink to &quot;1.2 优缺点&quot;">​</a></h4><ul><li>**优点：**更小文件的体积，通用浏览器和操作系统广泛支持。</li></ul><p>有损压缩：JPG格式具备出色的压缩性能，可以显著地减少图像文件的大小。这使得 它在Web上显示一些质量要求不高的图像非常有用，减少加载时间。</p><p>广泛支持：是一种通用格式，在计算机以及手机设备上都广泛支持。</p><p>色彩丰富：JPG支持24位颜色深度，因此可以显示百万种颜色。</p><p>可调质量：用户可根据使用场景来调图片质量，较高的图片质量，会导致图片尺寸较大。</p><ul><li>**缺点：**有损图像压缩可能导致较差的文本可读性。</li></ul><p>不支持透明：不能够创建带有透明背景的图像，PNG或GIF更适合这种情况。</p><p>损失性压缩：JPG是有损压缩，而且一旦压缩无法还原，会丢失一些细节。</p><p>不适合带有文本或线条的图片：JPG压缩在处理文本和线条方面不如其他格式好，可能会导致图像出现锯齿或模糊情况。</p><p>不适合Icon或者Logo：相对于PNG或GIF图，在尺寸上没有优势。</p><h4 id="_1-3-兼容情况" tabindex="-1">1.3 兼容情况 <a class="header-anchor" href="#_1-3-兼容情况" aria-label="Permalink to &quot;1.3 兼容情况&quot;">​</a></h4><ul><li><p>从1.0版开始支持所有主流浏览器（Chrome，Firefox，Safari等）；</p></li><li><p>默认情况下，所有主流操作系统的图像查看器和编辑器均支持该格式。</p></li></ul><h4 id="_1-4-应用场景" tabindex="-1">1.4 应用场景 <a class="header-anchor" href="#_1-4-应用场景" aria-label="Permalink to &quot;1.4 应用场景&quot;">​</a></h4><ul><li><p>博客和文章图像（如用户头像，产品图片等）的不错选择。</p></li><li><p>不用于信息图表（拥有很多小文本）或教程截图，因为图像里面的文字至关重要。</p></li></ul><h3 id="_2-png-–-web广泛使用的图像格式" tabindex="-1">2. PNG – Web广泛使用的图像格式 <a class="header-anchor" href="#_2-png-–-web广泛使用的图像格式" aria-label="Permalink to &quot;2. PNG – Web广泛使用的图像格式&quot;">​</a></h3><h4 id="_2-1-简介" tabindex="-1">2.1 简介 <a class="header-anchor" href="#_2-1-简介" aria-label="Permalink to &quot;2.1 简介&quot;">​</a></h4><p>PNG，英文全称为Portable Network Graphics PNG（便携式网络图形），也是一种栅格图形格式，但支持无损压缩，保证颜色之间的细节和对比度。特别是，PNG提供比JPEG更好的文本可读性。<strong>PNG文件采用LZ77算法的派生算法进行压缩，其结果是获得高的压缩比，不损失数据，保证颜色之间的细节和对比度。其设计目的是试图替代GIF和TIFF文件格式</strong></p><p>这使得PNG成为信息图形，横幅Banner，屏幕截图以及其他同时包含图像和文本的图形的最佳表达方式。常见格式如下：</p><ul><li><p>**png-8：**png-8相比gif对透明的支持更好，同等质量下，尺寸也更小。 非常适 合作为gif的替代品。但png-8也一个明显的不足就是不支持动画。这也是png-8没办法完全替代gif的重要原因。如果没有动画需求推荐使用png-8 来替代gif。</p></li><li><p>**png-24、png-32：**图片质量和bmp差不多，尺寸比bmp更小。尺寸上比 JPG、GIF更大，当然质量更高。</p></li></ul><h4 id="_2-2-优缺点" tabindex="-1">2.2 优缺点 <a class="header-anchor" href="#_2-2-优缺点" aria-label="Permalink to &quot;2.2 优缺点&quot;">​</a></h4><ul><li>**优点：**高质量（无损）图像和清晰可见的文本。</li></ul><p>支持透明度：PNG支持透明通道，允许创建带有透明背景的图像。</p><p>无损压缩：可以保持图片质量不损失细节。</p><p>广泛支持：PNG是一种通用格式，计算机或移动设备都支持。</p><ul><li><strong>缺点</strong>：复杂、色彩丰富图片尺寸大，不支持动画</li></ul><p>如果文件过多（特别是高分辨率图像），可能会严重影响网站加载速度。</p><h4 id="_2-3-兼容情况" tabindex="-1">2.3 兼容情况 <a class="header-anchor" href="#_2-3-兼容情况" aria-label="Permalink to &quot;2.3 兼容情况&quot;">​</a></h4><ul><li>主流浏览器（Chrome，Edge，Firefox，Internet Explorer，Opera，Safari）支持。</li><li>主流操作系统及其标准图像编辑器都支持。</li></ul><h4 id="_2-4-应用场景" tabindex="-1">2.4 应用场景 <a class="header-anchor" href="#_2-4-应用场景" aria-label="Permalink to &quot;2.4 应用场景&quot;">​</a></h4><ul><li>信息图表，横幅，博客图形，屏幕截图，优惠券和其他包含文本的视觉效果的不错选择。</li><li>不要在网站上使用高分辨率的照片，因为文件体积可能会高达几MB。</li></ul><h3 id="_3-gif-–-动画图像格式" tabindex="-1">3. GIF – 动画图像格式 <a class="header-anchor" href="#_3-gif-–-动画图像格式" aria-label="Permalink to &quot;3. GIF – 动画图像格式&quot;">​</a></h3><h4 id="_3-1-简介" tabindex="-1">3.1 简介 <a class="header-anchor" href="#_3-1-简介" aria-label="Permalink to &quot;3.1 简介&quot;">​</a></h4><img src="'+s+'" alt="月亮, 月相, 夜晚, 满的, 一半, 新月, 游戏中时光倒流, Gif" style="zoom:50%;"><p>GIF，英文全称为Graphics Interchange Format，属于另一种栅格格式图像文件类型。其 <strong>带透明通道</strong>，体积小、成像相对清晰，特别适合于初期慢速的互联网，而大受欢迎。分为静态GIF和动画GIF两种，支持透明背景图像，适用于多种操作系统，“体型”很小，网上很多小动画都是GIF格式。该格式也使用了无损压缩，且将图像“约束”为8 bits/每个像素，并限制为256色调色板。</p><p>GIF格式也是最有名的（和最常用）的动画图像，因为它的8-bit限制保证了动画体积更小，并且对互联网很友好。</p><h4 id="_3-2-优缺点" tabindex="-1">3.2 优缺点 <a class="header-anchor" href="#_3-2-优缺点" aria-label="Permalink to &quot;3.2 优缺点&quot;">​</a></h4><p>**优点：**更小的文件体积和支持动画和透明。</p><p>**缺点：**8-bit限制代表图像质量受限，只能存储8位颜色索引，色彩复杂、细节丰富的图片不适合。</p><h4 id="_3-3-兼容情况" tabindex="-1">3.3 兼容情况 <a class="header-anchor" href="#_3-3-兼容情况" aria-label="Permalink to &quot;3.3 兼容情况&quot;">​</a></h4><ul><li>主流浏览器（Chrome，Edge，Firefox，Internet Explorer，Opera，Safari）及其标准图像编辑器都支持。</li></ul><h4 id="_3-4-应用场景" tabindex="-1">3.4 应用场景 <a class="header-anchor" href="#_3-4-应用场景" aria-label="Permalink to &quot;3.4 应用场景&quot;">​</a></h4><ul><li><p>使用GIF不仅可以“增加内容趣味”，还可以在教程和指南中演示相关操作和流程。</p></li><li><p>如果需要比8-bit彩色图像更清晰的图片就不要用（JPEG最多可支持24-bit）。</p></li></ul><h3 id="_4-webp-–-jpeg-png最佳替代图像格式" tabindex="-1">4. WebP – JPEG&amp;PNG最佳替代图像格式 <a class="header-anchor" href="#_4-webp-–-jpeg-png最佳替代图像格式" aria-label="Permalink to &quot;4. WebP – JPEG&amp;PNG最佳替代图像格式&quot;">​</a></h3><h4 id="_4-1-简介" tabindex="-1">4.1 简介 <a class="header-anchor" href="#_4-1-简介" aria-label="Permalink to &quot;4.1 简介&quot;">​</a></h4><p><strong>WebP</strong>：（Web Picture）是一种现代的图像格式，由Google开发，旨在提供高质量的图像压缩和更快的加载速度。是JPEG和PNG最佳替代图像格式。WebP致力于提供相同质量的图片，但文件尺寸较小。通过减少图片文件的大小，而不会“降低图片呈现质量导致糟糕用户体验”，并且有利于网站加载速度提升。</p><img src="'+o+'" alt="tiger-jpg" style="zoom:25%;"><p>在<a href="https://www.wbolt.com/go?_=3b0cc3b8bfaHR0cHM6Ly9kZXZlbG9wZXJzLmdvb2dsZS5jb20vc3BlZWQvd2VicC9kb2NzL3dlYnBfc3R1ZHk%3D" target="_blank" rel="noreferrer">Google的WebP压缩研究中</a>，Google发现平均一个WebP图片文件</p><ul><li>比JPEG图片小25-34％。</li><li>比PNG图片小26％。</li></ul><p>说明：当然我也不清楚为什么上边这个图在我转成webp格式后反而还比之前的jpg更大了，不是很理解，可能是在线转的问题？反正知道webp格式的特点就可以啦。</p><p>那么Google的WebP格式如何实现文件大小减少？WebP支持有损和无损压缩，因此确切的减少取决于我们使用的是有损还是无损压缩。通过有损的WebP压缩，WebP使用一种称为“预测编码”的方法来减小文件大小。预测编码使用图片中相邻像素的值来预测值，然后仅对差异进行编码。它基于VP8关键帧编码。无损WebP使用WebP团队开发的一套更为复杂的方法。如果想详细了解WebP压缩技术，那么<a href="https://www.wbolt.com/go?_=8616d760baaHR0cHM6Ly9kZXZlbG9wZXJzLmdvb2dsZS5jb20vc3BlZWQvd2VicC9kb2NzL2NvbXByZXNzaW9u" target="_blank" rel="noreferrer">可以阅读谷歌相关文档</a>。</p><blockquote><p>Google关于WebP的一些说明资料：<a href="https://www.wbolt.com/go?_=85af9be07eaHR0cHM6Ly9kZXZlbG9wZXJzLmdvb2dsZS5jb20vc3BlZWQvd2VicC9kb2NzL3dlYnBfbG9zc2xlc3NfYWxwaGFfc3R1ZHk%3D" target="_blank" rel="noreferrer">Lossless and Transparency Encoding in WebP</a>，<a href="https://www.wbolt.com/go?_=3b0cc3b8bfaHR0cHM6Ly9kZXZlbG9wZXJzLmdvb2dsZS5jb20vc3BlZWQvd2VicC9kb2NzL3dlYnBfc3R1ZHk%3D" target="_blank" rel="noreferrer">WebP Compression Study</a>。</p></blockquote><h4 id="_4-2-优缺点" tabindex="-1">4.2 优缺点 <a class="header-anchor" href="#_4-2-优缺点" aria-label="Permalink to &quot;4.2 优缺点&quot;">​</a></h4><ul><li>**优点：**较小的文件即可获得相同或更好的图像质量。</li></ul><p>高压缩率：WebP 图像通常具有更小的文件大小，相对于传统格式如JPEG和PNG，可以减少带宽使用和加速页面加载速度</p><p>高质量：即使在较高的压缩率下，WebP 图像通常能够保持较高的图像质量，减少了压缩损失。</p><p>透明度：WebP支持透明通道，可以用于创建带有透明背景的图像，类似于PNG格式。</p><p>动画：WebP还支持动画图像，允许创建小型、高质量的动画。</p><p>广泛支持：大多数浏览器都已经支持，但是目前低版本的Safri以及IE还不支持。</p><ul><li>**缺点：**并非所有浏览器和图像编辑器都支持。</li></ul><h4 id="_4-3-兼容情况" tabindex="-1">4.3 兼容情况 <a class="header-anchor" href="#_4-3-兼容情况" aria-label="Permalink to &quot;4.3 兼容情况&quot;">​</a></h4><p>为了使WebP图片起作用，需要Web浏览器兼容才行。不幸的是，尽管越来越多的浏览器开始兼容WebP，但<strong>WebP兼容性仍然不是通用的</strong>。大多数计算器系统自带的图像编辑器仍不支持该格式，但Photoshop等专业软件均支持WebP。</p><p>当前主流浏览器一般都支持WebP图片（冥顽不灵的IE依然是不支持的，也可能因为它不是开源的），例如：</p><ul><li>Chrome（PC设备为17+版本，移动设备为25+版本））</li><li>Firefox（PC&amp;移动设备 65+版本）</li><li>Edge（18+）</li><li>Opera（PC&amp;移动设备11.0+版本）</li></ul><p>值得注意的是Safari，Safari的桌面版和移动版均不支持WebP图片。Apple在2016年<a href="https://www.wbolt.com/go?_=c4e1262f8daHR0cHM6Ly93d3cuY25ldC5jb20vbmV3cy9hcHBsZS1pb3MtbWFjb3MtdGVzdHMtZ29vZ2xlcy13ZWJwLWdyYXBoaWNzLXRvLXNwZWVkLXVwLXdlYi8%3D" target="_blank" rel="noreferrer">曾尝试Safari兼容WebP的开发</a>，但此后就渺无音讯了。</p><p>Internet Explorer也不兼容WebP（Edge支持WebP，因为它基于Chromium）。</p><p>总计，<a href="https://www.wbolt.com/go?_=f04f845672aHR0cHM6Ly9jYW5pdXNlLmNvbS8jZmVhdD13ZWJw" target="_blank" rel="noreferrer">大约77％互联网用户</a>使用支持WebP的浏览器。但23％的数字太大了，不容忽视：</p><img src="'+n+`" alt="WebP支持" style="zoom:50%;"><p><strong>兼容性处理</strong>：</p><ul><li>前端做处理：</li></ul><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">picture</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;  </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">source</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;image/webp&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> srcset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;flower.webp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;  </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">source</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;image/jpeg&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> srcset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;flower.jpg&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;  </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./flower.jpg&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> alt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">picture</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><ul><li>后端处理：</li></ul><p>如果图片资源存储在服务端，可以设计一套通用方案，在服务端根据Accept请求头判断是否支持Webp格式，如果支持返回Webp格式，否则返回PNG格式</p><h4 id="_4-4-应用场景" tabindex="-1">4.4 应用场景 <a class="header-anchor" href="#_4-4-应用场景" aria-label="Permalink to &quot;4.4 应用场景&quot;">​</a></h4><p>JPEG和PNG文件最佳替代格式，可节省带宽并提升网站加载速度。</p><p>（1）WebP 格式适用于网页开发，特别是那些需要快速加载的网站和移动应用程序。</p><p>（2）适合用于图像库、图标、按钮、背景图像、动画以及需要高质量和小文件大小的图像。</p><p>（3）WebP 的无损压缩特性使它适用于医学图像、卫星图像、地图和其他需要高质量和完整性的图像应用。</p><h3 id="_5-tiff-–-扫描仪最佳拍档图像格式" tabindex="-1">5. TIFF – 扫描仪最佳拍档图像格式 <a class="header-anchor" href="#_5-tiff-–-扫描仪最佳拍档图像格式" aria-label="Permalink to &quot;5. TIFF – 扫描仪最佳拍档图像格式&quot;">​</a></h3><h4 id="_5-1-简介" tabindex="-1">5.1 简介 <a class="header-anchor" href="#_5-1-简介" aria-label="Permalink to &quot;5.1 简介&quot;">​</a></h4><p>TIFF是“Tagged Image File Format”的缩写，是一种光栅图像格式，最常用于存储和编辑图像，以便于将来打印，它<strong>是一种可跨软件进行原图层编辑的图片格式</strong>。该格式不支持任何压缩，图像质量是该格式的首要保证。它的图标如下：</p><img src="`+h+'" alt="tiff-icon" style="zoom:25%;"><h4 id="_5-2-优缺点" tabindex="-1">5.2 优缺点 <a class="header-anchor" href="#_5-2-优缺点" aria-label="Permalink to &quot;5.2 优缺点&quot;">​</a></h4><p>**优点：**高质量文件适合存储或印刷出版。</p><p>**缺点：**不支持压缩导致图像文件体积过大；非常有限的浏览器支持。</p><h4 id="_5-3-兼容情况" tabindex="-1">5.3 兼容情况 <a class="header-anchor" href="#_5-3-兼容情况" aria-label="Permalink to &quot;5.3 兼容情况&quot;">​</a></h4><ul><li>主流浏览器在没有附加组件或扩展的情况下不支持TIFF文件。</li><li>一般为专业图像编辑和发布工具的其中一种导出格式。</li></ul><h4 id="_5-4-应用场景" tabindex="-1">5.4 应用场景 <a class="header-anchor" href="#_5-4-应用场景" aria-label="Permalink to &quot;5.4 应用场景&quot;">​</a></h4><ul><li>存储和准备要出版印刷的图像和图形。</li><li>许多扫描仪以该格式文件保存高质量扫描文档或图片。</li></ul><h3 id="_6-bmp-—-过气的图像格式" tabindex="-1">6. BMP — 过气的图像格式 <a class="header-anchor" href="#_6-bmp-—-过气的图像格式" aria-label="Permalink to &quot;6. BMP — 过气的图像格式&quot;">​</a></h3><h4 id="_6-1-简介" tabindex="-1">6.1 简介 <a class="header-anchor" href="#_6-1-简介" aria-label="Permalink to &quot;6.1 简介&quot;">​</a></h4><p><a href="https://www.wikiwand.com/zh-hans/BMP" target="_blank" rel="noreferrer">BMP</a>取自位图<strong>B</strong>it<strong>m</strong>a<strong>p</strong>的缩写，也称为<strong>DIB</strong>（与<a href="https://www.wikiwand.com/zh-hans/%E8%AE%BE%E5%A4%87" target="_blank" rel="noreferrer">设备</a>无关的<strong>位图</strong>），是一种独立于<a href="https://www.wikiwand.com/zh-hans/%E6%98%BE%E7%A4%BA%E5%99%A8" target="_blank" rel="noreferrer">显示器</a>的<a href="https://www.wikiwand.com/zh-hans/%E4%BD%8D%E5%9B%BE" target="_blank" rel="noreferrer">位图</a><a href="https://www.wikiwand.com/zh-hans/%E6%95%B0%E5%AD%97%E5%9B%BE%E5%83%8F" target="_blank" rel="noreferrer">数字图像</a>文件格式。常见于<a href="https://www.wikiwand.com/zh-hans/%E5%BE%AE%E8%BD%AF%E8%A7%86%E7%AA%97" target="_blank" rel="noreferrer">微软视窗</a>和<a href="https://www.wikiwand.com/zh-hans/OS/2" target="_blank" rel="noreferrer">OS/2</a>操作系统，Windows GDI API内部使用的DIB<a href="https://www.wikiwand.com/zh-hans/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84" target="_blank" rel="noreferrer">数据结构</a>与 BMP 文件格式几乎相同。</p><p>图像通常保存的<a href="https://www.wikiwand.com/zh-hans/%E9%A2%9C%E8%89%B2%E6%B7%B1%E5%BA%A6" target="_blank" rel="noreferrer">颜色深度</a>有2（1位）、16（4位）、256（8位）、65536（16位）和约1677万（24位）种颜色（其中位是表示每点所用的数据位）。8位图像可以是索引彩色图像外，也可以是灰阶图像。表示透明（英语：<a href="https://en.wikipedia.org/wiki/transparency_(graphic)" target="_blank" rel="noreferrer">transparency (graphic)</a>）的<a href="https://www.wikiwand.com/zh-hans/Alpha%E9%80%9A%E9%81%93" target="_blank" rel="noreferrer">alpha通道</a>也可以保存在一个类似于<a href="https://www.wikiwand.com/zh-hans/%E7%81%B0%E9%9A%8E" target="_blank" rel="noreferrer">灰阶</a>图像的独立文件中。带有集成的alpha通道的32位版本已经随着<a href="https://www.wikiwand.com/zh-hans/Windows_XP" target="_blank" rel="noreferrer">Windows XP</a>出现，它在<a href="https://www.wikiwand.com/zh-hans/Windows%E7%B3%BB%E7%B5%B1" target="_blank" rel="noreferrer">Windows系统</a>的登录界面和系统主题中都有使用。</p><p>它基本算是一种已经过时的图像文件格式，几乎不压缩情况映射像素。这意味着BMP文件体积经常会比较庞大，不利于存储或处理。</p><img src="'+p+'" alt="bmp-vs-gif" style="zoom:50%;"><h4 id="_6-2-优缺点" tabindex="-1">6.2 优缺点 <a class="header-anchor" href="#_6-2-优缺点" aria-label="Permalink to &quot;6.2 优缺点&quot;">​</a></h4><ul><li><strong>优点</strong>：尽管文件大小比较大，但是位图文件的简单性、在微软视窗和其他地方的广泛使用以及这种格式的优秀文档标准以及没有<a href="https://www.wikiwand.com/zh-hans/%E4%B8%93%E5%88%A9" target="_blank" rel="noreferrer">专利</a>约束，使得它成为其他操作系统图像处理程序能够读写的一种最为常用的格式。</li><li><strong>缺点</strong>：与WebP，GIF或PNG等格式相比，体积又大又没有质量上的提升。</li></ul><h4 id="_6-3-兼容情况" tabindex="-1">6.3 兼容情况 <a class="header-anchor" href="#_6-3-兼容情况" aria-label="Permalink to &quot;6.3 兼容情况&quot;">​</a></h4><ul><li>主流浏览器（Chrome，Edge，Firefox，Internet Explorer，Opera，Safari）都支持。</li><li>大多数系统默认图像编辑器（例如MS Paint）支持。</li></ul><h4 id="_6-4-应用场景" tabindex="-1">6.4 应用场景 <a class="header-anchor" href="#_6-4-应用场景" aria-label="Permalink to &quot;6.4 应用场景&quot;">​</a></h4><p>接触的确实不多，没怎么见过bmp文件了。</p><h3 id="_7-heif-–-手机照片常见图像格式" tabindex="-1">7. HEIF – 手机照片常见图像格式 <a class="header-anchor" href="#_7-heif-–-手机照片常见图像格式" aria-label="Permalink to &quot;7. HEIF – 手机照片常见图像格式&quot;">​</a></h3><h4 id="_7-1-简介" tabindex="-1">7.1 简介 <a class="header-anchor" href="#_7-1-简介" aria-label="Permalink to &quot;7.1 简介&quot;">​</a></h4><p><a href="https://www.wikiwand.com/zh-hans/%E9%AB%98%E6%95%88%E7%8E%87%E5%9B%BE%E5%83%8F%E6%96%87%E4%BB%B6%E6%A0%BC%E5%BC%8F" target="_blank" rel="noreferrer">HEIF</a>，是High Efficiency Image File Format的缩写，是由MPEG视频格式背后的技术团队开发的图像格式，是JPEG的直接竞争对手。HEIF压缩效率理论值几乎是JPEG的两倍，换言之，文件大小相同的情况下，HEIF图像质量可以提高一倍。这是一种基于像素映射的光栅图像格式，无法做到按比例放大图像而不会降低质量。</p><img src="'+d+'" alt="jpeg-vs-heif-1024x307"><p>HEIF规范也定义了<a href="https://www.wikiwand.com/zh-hans/%E9%AB%98%E6%95%88%E7%8E%87%E8%A7%86%E9%A2%91%E7%BC%96%E7%A0%81" target="_blank" rel="noreferrer">高效率视频编码</a>（HEVC）编码的<a href="https://www.wikiwand.com/zh-hans/%E8%A6%96%E8%A8%8A%E5%A3%93%E7%B8%AE%E5%9C%96%E5%83%8F%E9%A1%9E%E5%9E%8B" target="_blank" rel="noreferrer">内嵌图像</a>和HEVC编码的图像序列的存储方式，其中以受约束的方式应用帧间预测（英语：<a href="https://en.wikipedia.org/wiki/Inter_frame" target="_blank" rel="noreferrer">Inter frame</a>）。</p><p>HEIF文件与ISO基本媒体文件格式（英语：<a href="https://en.wikipedia.org/wiki/ISO_base_media_file_format" target="_blank" rel="noreferrer">ISO base media file format</a>）（ISOBMFF，ISO/IEC 14496-12）兼容，并且还可以包括其他媒体流，例如定时的文本和音频。</p><h4 id="_7-2-优缺点" tabindex="-1">7.2 优缺点 <a class="header-anchor" href="#_7-2-优缺点" aria-label="Permalink to &quot;7.2 优缺点&quot;">​</a></h4><ul><li><strong>优点</strong>：相对于JPG来说，同等质量下，可以做到压缩效率更高。</li><li><strong>缺点</strong>浏览器不支持和有限的操作系统支持。</li></ul><h4 id="_7-3-兼容情况" tabindex="-1">7.3 兼容情况 <a class="header-anchor" href="#_7-3-兼容情况" aria-label="Permalink to &quot;7.3 兼容情况&quot;">​</a></h4><ul><li>所有<a href="https://www.wbolt.com/go?_=0219d47572aHR0cHM6Ly93d3cuY2FuaXVzZS5jb20vP3NlYXJjaD1IRUlG" target="_blank" rel="noreferrer">主流浏览器均不支持</a>。</li><li>在macOS Sierra和iOS 11以上版本系统兼容支持，但Safari浏览器又不支持。</li></ul><h4 id="_7-4-应用场景" tabindex="-1">7.4 应用场景 <a class="header-anchor" href="#_7-4-应用场景" aria-label="Permalink to &quot;7.4 应用场景&quot;">​</a></h4><ul><li>一些相机中会有支持HEIF格式，例如索尼，我自己的A7C2就有。</li><li>后来新出的苹果手机一般都支持，有一些安卓手机也可能会使用。</li></ul><h3 id="_8-svg-–-可缩放矢量图形格式" tabindex="-1">8. SVG – 可缩放矢量图形格式 <a class="header-anchor" href="#_8-svg-–-可缩放矢量图形格式" aria-label="Permalink to &quot;8. SVG – 可缩放矢量图形格式&quot;">​</a></h3><h4 id="_8-1-简介" tabindex="-1">8.1 简介 <a class="header-anchor" href="#_8-1-简介" aria-label="Permalink to &quot;8.1 简介&quot;">​</a></h4><p>可伸缩矢量图形文件格式（通常称为SVG），由W3C开发的一种标记语言，可以在浏览器中直接渲染为二维图像。它不像栅格格式那样依赖像素，而是使用XML文本以类似于数学方程式计算勾勒形状和线条获得图形，<strong>svg格式的文件会比较小，同时也能提供高清晰的画面，适合于直接打印或输出。</strong>。也就是说，可以在不损失任何质量的情况下无限放大SVG图像。</p><img src="'+b+'" alt="1200px-SVG_logo.svg_" style="zoom:15%;"><h4 id="_8-2-优缺点" tabindex="-1">8.2 优缺点 <a class="header-anchor" href="#_8-2-优缺点" aria-label="Permalink to &quot;8.2 优缺点&quot;">​</a></h4><ul><li><p>**优点：**体积小和无损缩放，可用于简单的插图，形状和文本。</p></li><li><p>**缺点：**对于图像或复杂图形而言，不是理想的格式。</p></li></ul><h4 id="_8-3-兼容情况" tabindex="-1">8.3 兼容情况 <a class="header-anchor" href="#_8-3-兼容情况" aria-label="Permalink to &quot;8.3 兼容情况&quot;">​</a></h4><ul><li>主流浏览器（Chrome，Edge，Firefox，Internet Explorer，Opera，Safari）都支持。</li><li>默认图像编辑器通常不支持SVG，但是大多数插画软件都支持SVG导出。</li></ul><h4 id="_8-4-应用场景" tabindex="-1">8.4 应用场景 <a class="header-anchor" href="#_8-4-应用场景" aria-label="Permalink to &quot;8.4 应用场景&quot;">​</a></h4><ul><li><p>主流浏览器（Chrome，Edge，Firefox，Internet Explorer，Opera，Safari）都支持。</p></li><li><p>默认图像编辑器通常不支持SVG，但是大多数插画软件都支持SVG导出。</p></li></ul><h3 id="_9-eps-–-插画-排版设计矢量图像格式" tabindex="-1">9. EPS – 插画/排版设计矢量图像格式 <a class="header-anchor" href="#_9-eps-–-插画-排版设计矢量图像格式" aria-label="Permalink to &quot;9. EPS – 插画/排版设计矢量图像格式&quot;">​</a></h3><h4 id="_9-1-简介" tabindex="-1">9.1 简介 <a class="header-anchor" href="#_9-1-简介" aria-label="Permalink to &quot;9.1 简介&quot;">​</a></h4><p>EPS（全称为Encapsulated PostScript）文件属于矢量图像文件，一般为Adobe Illustrator和其他插插画软件（如CorelDraw）的一种保存格式。</p><p>与SVG文件相似，EPS实际上是一个基于文本的文档格式，该文档使用代码表达形状和线条，而不是映射像素和颜色。因此，EPS文件也支持无损缩放。</p><img src="'+c+'" alt="pasted-image-0-3" style="zoom:25%;"><h4 id="_9-2-优缺点" tabindex="-1">9.2 优缺点 <a class="header-anchor" href="#_9-2-优缺点" aria-label="Permalink to &quot;9.2 优缺点&quot;">​</a></h4><ul><li><strong>优点</strong>：无损缩放，打印机支持的文档和设计。</li><li><strong>缺点</strong>：有限的软件支持，一般为IIIustrator、Quard Xpress、PageMaker等软件；Photoshop和Coreldraw可打开但不能编辑。</li></ul><h4 id="_9-3-兼容情况" tabindex="-1">9.3 兼容情况 <a class="header-anchor" href="#_9-3-兼容情况" aria-label="Permalink to &quot;9.3 兼容情况&quot;">​</a></h4><ul><li>EPS不是标准的Web图像文件格式，所有浏览器都不支持EPS。</li><li>几乎每个绘画程序及大多数页面布局程序都允许保存EPS文档。</li></ul><h4 id="_9-4-应用场景" tabindex="-1">9.4 应用场景 <a class="header-anchor" href="#_9-4-应用场景" aria-label="Permalink to &quot;9.4 应用场景&quot;">​</a></h4><ul><li>使用Adobe Illustrator或其他页面排版软件时，用于存储，保存和打印。</li></ul><h3 id="_10-raw-–-数码相机图像存储文件格式" tabindex="-1">10. Raw – 数码相机图像存储文件格式 <a class="header-anchor" href="#_10-raw-–-数码相机图像存储文件格式" aria-label="Permalink to &quot;10. Raw – 数码相机图像存储文件格式&quot;">​</a></h3><h4 id="_10-1-简介" tabindex="-1">10.1 简介 <a class="header-anchor" href="#_10-1-简介" aria-label="Permalink to &quot;10.1 简介&quot;">​</a></h4><p>Raw图像格式是数码相机用来存储高质量图像以供后期制作和编辑的文件类型。相机制造商的主要Raw图像文件类型：</p><ul><li>柯达：CR，K25，KDC</li><li>佳能：CRW CR2 CR3</li><li>爱普生：ERF</li><li>尼康：NEF NRW</li><li>奥林巴斯：ORF</li><li>宾得：PEF</li><li>松下：RW2</li><li>索尼：ARW，SRF，SR2</li></ul><p>RAW文件在一张图片中包含多达16,384种不同的颜色，而不是JPEG文件仅包含256种颜色。也就是说RAW文件在调整颜色和对比度等后期处理时，有着更大的灵活性。<strong>RAW图像不适合用于网络演示或共享</strong>，并且主流浏览器或图像查看器兼容性极差，一般需要使用专业的相机图像处理软件处理。</p><h4 id="_10-2-优缺点" tabindex="-1">10.2 优缺点 <a class="header-anchor" href="#_10-2-优缺点" aria-label="Permalink to &quot;10.2 优缺点&quot;">​</a></h4><ul><li><strong>优点</strong>：更高质量的图片，色彩变化更大。</li><li><strong>确定</strong>：图像文件超级大（RAW文件体积随便就20-40MB）。</li></ul><h4 id="_10-3-兼容情况" tabindex="-1">10.3 兼容情况 <a class="header-anchor" href="#_10-3-兼容情况" aria-label="Permalink to &quot;10.3 兼容情况&quot;">​</a></h4><p>这个要看软件的支持情况了。</p><h4 id="_10-4-应用场景" tabindex="-1">10.4 应用场景 <a class="header-anchor" href="#_10-4-应用场景" aria-label="Permalink to &quot;10.4 应用场景&quot;">​</a></h4><ul><li>以最高质量保存照片以进行后期处理和编辑。一般在摄影上用的多，他可以保留大量的细节和色彩信息，为后期提供了巨大的可操作空间。</li></ul>',156)])])}const _=e(u,[["render",g]]);export{q as __pageData,_ as default};
